// ─── File: NoPointersDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.ptr;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class NoPointersDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRegistry registry = new AccountRegistry();
        registry.add(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        registry.add(new Account("CUR3001", "Priya",  new BigDecimal("250000")));

        // Lookup is by logical id — never by a raw memory address.
        Account rajesh = registry.find("SAV2001");
        log.info(() -> "Found by id (not address): " + rajesh.getHolderName()
                + " Rs." + rajesh.getBalance());

        // References stay valid even though the JVM may MOVE objects during
        // compacting GC — the JVM updates managed references, code is unaffected.
        System.gc(); // hint; object may be relocated internally, ref still works
        log.info(() -> "After possible GC relocation, ref still valid: "
                + rajesh.getHolderName());

        // Bounds checking: no pointer arithmetic can walk off the array.
        SafeArrayAccess safe = new SafeArrayAccess();
        BigDecimal[] balances = { rajesh.getBalance(), registry.find("CUR3001").getBalance() };
        safe.readOrReject(balances, 1);  // valid index
        safe.readOrReject(balances, 99); // out of range → exception, NOT corruption
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in AccountRegistry.java (lookup by id, never by address) ───
class AccountRegistry {
    private final java.util.Map<String, Account> byId = new java.util.HashMap<>();
    void add(Account a) { byId.put(a.getAccountId(), a); }
    Account find(String id) { return byId.get(id); } // managed reference, not a raw pointer
}

// ─── Would be in SafeArrayAccess.java (bounds-checked) ───
class SafeArrayAccess {
    private static final Logger log = Logger.getLogger("BankLog");

    void readOrReject(BigDecimal[] arr, int index) {
        try {
            // JVM bounds-checks every access; no pointer arithmetic possible.
            BigDecimal value = arr[index];
            log.info(() -> "Read index " + index + " = Rs." + value);
        } catch (ArrayIndexOutOfBoundsException e) {
            // Safety: out-of-range is a clean exception, not memory corruption.
            log.severe(() -> "Rejected index " + index + ": "
                    + "no arbitrary memory access (safe failure, not a crash)");
        }
    }
}
